from typing import Optional

from fastapi import Depends, FastAPI, Header, HTTPException
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Invoices")


@app.get("/invoices")
def list_invoices(
    sort_by: str = "created_at",
    order: str = "desc",
    status: Optional[str] = None,
    x_tenant_id: int = Header(...),
    db=Depends(get_db),
):
    params = {"tenant": x_tenant_id}
    status_clause = ""
    if status:
        status_clause = "AND status = :status"
        params["status"] = status

    if sort_by not in {"id", "customer", "amount_cents", "status", "created_at"} or order not in {"asc", "desc"}:
        raise HTTPException(status_code=422, detail="invalid sort")
    sql = (
        f"SELECT id, customer, amount_cents, status, created_at FROM invoices "
        f"WHERE tenant_id = :tenant {status_clause} ORDER BY {sort_by} {order}"
    )
    query = text(sql)
    rows = db.execute(query, params).mappings().all()
    return [
        {**row, "created_at": row["created_at"].isoformat()}
        for row in rows
    ]

from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel, Field
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Invoice splitting")


class SplitRequest(BaseModel):
    payers: int = Field(ge=1, le=20)


@app.post("/invoices/{invoice_id}/split")
def split_invoice(invoice_id: int, body: SplitRequest, db=Depends(get_db)):
    amount = db.execute(
        text("SELECT amount_cents FROM invoices WHERE id = :id"), {"id": invoice_id}
    ).scalar()
    if amount is None:
        raise HTTPException(status_code=404, detail="Invoice not found")

    base, remainder = divmod(amount, body.payers)
    shares = [base + 1 if i < remainder else base for i in range(body.payers)]
    return {"invoice_id": invoice_id, "amount_cents": amount, "shares": shares}

