        raise HTTPException(status_code=404, detail="User not found")
    return dict(row)


EDITABLE = {"display_name", "email", "timezone"}


@app.get("/users/me")
def me(x_user_id: int = Header(...), db=Depends(get_db)):
    return load(db, x_user_id)


@app.patch("/users/me")
def update_me(changes: dict = Body(...), x_user_id: int = Header(...), db=Depends(get_db)):
    load(db, x_user_id)
    forbidden = sorted(set(changes) - EDITABLE)
    if forbidden:
        raise HTTPException(status_code=422, detail=f"Fields that cannot be changed: {forbidden}")
    if changes:
        db.execute(update(users).where(users.c.id == x_user_id).values(**changes))
        db.commit()
    return load(db, x_user_id)

