"""Mid-cycle plan changes.

Billing periods are half-open date ranges [period_start, period_end): period_end is the
first day of the NEXT period. When a plan changes on `effective_date`, the customer is
credited for the unused part of the old plan and charged for the rest of the period on the
new plan. The remaining part runs from effective_date (inclusive) to period_end, and it is
measured in days against the real length of the period (28-31 days). Each amount is rounded
to the nearest cent, with halves rounded up.
"""

from datetime import date
from decimal import ROUND_HALF_UP, Decimal

from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Subscriptions")


class PlanChange(BaseModel):
    new_plan_id: int
    effective_date: date


def plan_price(db, plan_id: int) -> int:
    price = db.execute(
        text("SELECT monthly_cents FROM plans WHERE id = :id"), {"id": plan_id}
    ).scalar()
    if price is None:
        raise HTTPException(status_code=404, detail="Plan not found")
    return price


def prorate(price_cents: int, remaining_days: int, period_start: date, period_end: date) -> int:
    days_in_period = (period_end - period_start).days
    return round(price_cents * remaining_days / days_in_period)


@app.post("/subscriptions/{subscription_id}/change-plan")
def change_plan(subscription_id: int, body: PlanChange, db=Depends(get_db)):
    sub = db.execute(
        text("SELECT plan_id, period_start, period_end FROM subscriptions WHERE id = :id"),
        {"id": subscription_id},
    ).mappings().first()
    if sub is None:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if body.new_plan_id == sub["plan_id"]:
        raise HTTPException(status_code=422, detail="Already on this plan")
    if not sub["period_start"] <= body.effective_date < sub["period_end"]:
        raise HTTPException(status_code=422, detail="effective_date outside the current period")

    old_price = plan_price(db, sub["plan_id"])
    new_price = plan_price(db, body.new_plan_id)
    remaining = (sub["period_end"] - body.effective_date).days
    credit = prorate(old_price, remaining, sub["period_start"], sub["period_end"])
    charge = prorate(new_price, remaining, sub["period_start"], sub["period_end"])
    return {"credit_cents": credit, "charge_cents": charge, "net_cents": charge - credit}

"""Payment webhooks from the payment provider.

Every request carries a Payment-Signature header, "t=<unix seconds>,v1=<hex>", where v1 is the
HMAC-SHA256 of "<t>." followed by the raw request body, keyed with the webhook secret stored in
the settings table. The service must:
- reject a request whose signature is missing or invalid with 401, changing nothing
- reject a correctly signed event whose timestamp is more than 300 seconds away from now (in the
  past or in the future) with 400, changing nothing, so a captured request can't be replayed later
- process each event id once: a repeated event id returns {"status": "duplicate"} and changes nothing
- otherwise mark the event's invoice as paid and return {"status": "processed"}; unknown invoices are 404
"""

import hashlib
import hmac
import json
import time

from fastapi import Depends, FastAPI, Header, HTTPException, Request
from sqlalchemy import text

from app.db import get_db

app = FastAPI(title="Payment webhooks")

TOLERANCE_S = 300


def webhook_secret(db) -> bytes:
    return db.execute(text("SELECT value FROM settings WHERE key = 'webhook_secret'")).scalar_one().encode()


def header_parts(header: str) -> dict[str, str]:
    return dict(item.split("=", 1) for item in header.split(",") if "=" in item)


def signature_ok(secret: bytes, header: str, raw: bytes) -> bool:
    parts = header_parts(header)
    expected = hmac.new(secret, f"{parts.get('t', '')}.".encode() + raw, hashlib.sha256).hexdigest()
    return hmac.compare_digest(parts.get("v1", ""), expected)


@app.post("/webhooks/payment")
async def payment_event(request: Request, payment_signature: str | None = Header(None), db=Depends(get_db)):
    raw = await request.body()
    if payment_signature is None or not signature_ok(webhook_secret(db), payment_signature, raw):
        raise HTTPException(status_code=401, detail="Invalid signature")
    try:
        signed_at = int(header_parts(payment_signature)["t"])
    except (KeyError, ValueError):
        raise HTTPException(status_code=401, detail="Invalid signature")
    if abs(time.time() - signed_at) > TOLERANCE_S:
        raise HTTPException(status_code=400, detail="Event timestamp outside the tolerance")
    event = json.loads(raw)
    if db.execute(text("SELECT 1 FROM webhook_events WHERE event_id = :id"), {"id": event["id"]}).first():
        return {"status": "duplicate"}
    if db.execute(text("SELECT 1 FROM invoices WHERE id = :id"), {"id": event["invoice_id"]}).first() is None:
        raise HTTPException(status_code=404, detail="Invoice not found")
    db.execute(text("UPDATE invoices SET status = 'paid' WHERE id = :id"), {"id": event["invoice_id"]})
    db.execute(
        text("INSERT INTO webhook_events (event_id, invoice_id) VALUES (:id, :invoice)"),
        {"id": event["id"], "invoice": event["invoice_id"]},
    )
    db.commit()
    return {"status": "processed"}

